using System;using System.Linq;using System.Reflection;using UnityEngine;using Assets.Script.DynamicCards;public static class MotionWork{public static void Run(){Time.timeScale=0;foreach(var v in UnityEngine.Object.FindObjectsOfType<DynamicCardView>()){var t=v.GetType();var model=(GameObject)t.GetField("model",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(v);if(model==null)continue;foreach(var a in model.GetComponentsInChildren<Animator>(true)){if(a.runtimeAnimatorController==null)continue;var state=a.GetCurrentAnimatorStateInfo(0);a.Play(state.fullPathHash,0,.5f);a.Update(0);}t.GetField("age",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(v,5f);}}}